  if(c.name.equals("dev/zomboidmelee/mixin/VanillaCombatMixin"))for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof MethodInsnNode q&&q.owner.equals("dev/zomboidmelee/combat/PanelCooldown")&&q.name.equals("vanilla")){q.owner=B+"Boxing16";q.name="cooldown";changed=true;hits++;}
